-- Run this script in the empty database created for FitStock.
-- It creates the application schema only; it does not insert sample products or users.

BEGIN;

CREATE TABLE IF NOT EXISTS products (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(80) NOT NULL,
    "Sku" character varying(24) NOT NULL,
    "Category" text NOT NULL,
    "Unit" text NOT NULL,
    "Quantity" integer NOT NULL,
    "MinimumStock" integer NOT NULL,
    "UnitPrice" numeric(12,2) NOT NULL,
    "Zone" character varying(32) NOT NULL,
    "Condition" integer NOT NULL,
    "PurchaseDate" timestamp without time zone NOT NULL,
    "WarrantyUntil" timestamp without time zone NULL,
    "Notes" character varying(400) NULL,
    CONSTRAINT "PK_products" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_products_Sku" ON products ("Sku");

CREATE TABLE IF NOT EXISTS stock_movements (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "ProductName" character varying(80) NOT NULL,
    "Sku" character varying(24) NOT NULL,
    "Type" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "Unit" text NOT NULL,
    "Zone" text NOT NULL,
    "Note" character varying(120) NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_stock_movements" PRIMARY KEY ("Id")
);

CREATE INDEX IF NOT EXISTS "IX_stock_movements_CreatedAt" ON stock_movements ("CreatedAt");

CREATE TABLE IF NOT EXISTS warehouse_orders (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Number" text NOT NULL,
    "Customer" character varying(80) NOT NULL,
    "ProductId" integer NOT NULL,
    "ProductName" text NOT NULL,
    "Sku" text NOT NULL,
    "Quantity" integer NOT NULL,
    "UnitPrice" numeric(12,2) NOT NULL,
    "Status" integer NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_warehouse_orders" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_warehouse_orders_Number" ON warehouse_orders ("Number");

CREATE TABLE IF NOT EXISTS warehouse_users (
    "Id" uuid NOT NULL,
    "Login" character varying(50) NOT NULL,
    "Email" character varying(254) NOT NULL,
    "PasswordHash" character varying(500) NOT NULL,
    "Role" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_warehouse_users" PRIMARY KEY ("Id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_warehouse_users_Email" ON warehouse_users ("Email");

CREATE TABLE IF NOT EXISTS "__fitstock_migrations_history" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___fitstock_migrations_history" PRIMARY KEY ("MigrationId")
);

INSERT INTO "__fitstock_migrations_history" ("MigrationId", "ProductVersion")
VALUES ('202611170001_FitStockWarehouse', '8.0.0')
ON CONFLICT ("MigrationId") DO NOTHING;

COMMIT;
